mapper.sql:
WHERE achievement.deleted_yn = 'N'
AND achievement.management_no = #{criteria.normalizedManagementNo}
AND owner.login_id ILIKE CONCAT('%', #{criteria.normalizedTeacherName}, '%')
AND achievement.management_item_code = #{criteria.normalizedManagementItemCode}
AND achievement.certification_status = #{criteria.normalizedCertificationStatus}
AND 1 = 1
AND achievement.target_user_id = #{requesterUserId}
AND EXISTS ( SELECT 1 FROM organization_user_mappings requester_mapping JOIN organization_user_mappings target_mapping ON target_mapping.organization_code = requester_mapping.organization_code WHERE requester_mapping.user_id = #{requesterUserId} AND requester_mapping.status = 'ACTIVE' AND target_mapping.user_id = achievement.target_user_id AND target_mapping.status = 'ACTIVE' )
AND EXISTS ( SELECT 1 FROM evaluation_organization_mappings permission_mapping JOIN organization_user_mappings target_mapping ON target_mapping.organization_code = permission_mapping.organization_code WHERE permission_mapping.user_id = #{requesterUserId} AND permission_mapping.business_type = 'FACULTY_ACHIEVEMENT' AND permission_mapping.data_scope IN ('DEPARTMENT', 'COLLEGE', 'BUSINESS', 'ALL') AND target_mapping.user_id = achievement.target_user_id AND target_mapping.status = 'ACTIVE' )
AND 1 = 1
AND 1 = 0

mapper.select:
SELECT  FROM employment_rate_achievements achievement
JOIN users owner ON owner.user_id = achievement.target_user_id
 AND achievement.achievement_id = #{achievementId}

mapper.insert:
INSERT INTO employment_rate_achievements (
    management_no, target_user_id, evaluation_year, management_item_code, occurred_date,
    achievement_name, attachment_ref, certification_status, deleted_yn, created_by, updated_by
) VALUES (
    #{managementNo}, #{targetUserId}, #{evaluationYear}, #{managementItemCode}, #{achievementDate},
    #{achievementName}, #{attachmentRef}, 'DRAFT', 'N', #{createdBy}, #{createdBy}
)

INSERT INTO education_achievement_status_histories (
    achievement_type, achievement_id, previous_status, next_status, action_type,
    reason_code, opinion, processed_by, processed_at
) VALUES (
    #{history.achievementType}, #{history.achievementId}, #{history.previousStatus},
    #{history.nextStatus}, #{history.actionType}, #{history.reasonCode},
    #{history.opinion}, #{history.processedBy}, #{history.processedAt}
)

INSERT INTO data_change_histories (
    target_business, target_key, change_type, field_name, before_value,
    after_value, changed_by, change_reason, request_id
) VALUES (
    #{targetBusiness}, #{targetKey}, #{changeType}, #{fieldName}, #{beforeValue},
    #{afterValue}, #{changedBy}, #{changeReason}, #{requestId}
)
